function d_power(P,R){var loads=P.loads||[];var tot=loads.reduce(function(s,l){return s+l.w;},0);var gen=P.generation_W||1000;return{load_W:tot,generation_W:gen,margin_W:gen-tot,margin_pct:+((gen-tot)/Math.max(1,gen)*100).toFixed(1),ok:gen>=tot};}

